func (this *Mexc) watchSwapPrivateBody(ch chan any, messageHash any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var channel string = "login"
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "swap"))
	var timestamp string = strconv.FormatInt(this.Milliseconds(), 10)
	var payload any = ccxt.Add(this.ApiKey, timestamp)
	var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), ccxt.Sha256)
	var request map[string]any = map[string]any{
		"method": channel,
		"param": map[string]any{
			"apiKey":    this.ApiKey,
			"signature": signature,
			"reqTime":   timestamp,
		},
	}
	var message map[string]any = this.Extend(request, params)

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, message, channel)))
	return nil
}

/**
 * @method
 * @name mexc#watchOHLCV
 * @see https://www.mexc.com/api-docs/spot-v3/websocket-market-streams/k-line-streams // spot
 * @see https://www.mexc.com/api-docs/futures/websocket-api/k-line-data // swap
 * @description watches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch ccxt.OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Mexc) WatchOHLCVAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Mexc) watchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var timeframe string = ccxt.GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var symbolValue *string = ccxt.SafeStringPtr(market["symbol"])
	var timeframes map[string]any = ccxt.SafeMapTyped(this.Options, "timeframes")
	var timeframeId *string = this.SafeString(timeframes, timeframe)
	var messageHash string = "candles:" + *symbolValue + ":" + timeframe
	var ohlcv any = nil
	if ccxt.GetValue(market, "spot") == true {
		var channel *string = ccxt.SafeStringPtr(ccxt.Add(ccxt.Add(ccxt.Add("spot@public.kline.v3.api.pb@", market["id"]), "@"), timeframeId))

		ohlcv = (<-this.WatchSpotPublicAsync(channel, messageHash, params))
		ccxt.PanicOnError(ohlcv)
	} else {
		var channel string = "sub.kline"
		var requestParams map[string]any = map[string]any{
			"symbol":   market["id"],
			"interval": timeframeId,
		}

		ohlcv = (<-this.WatchSwapPublicAsync(channel, messageHash, requestParams, params))
		ccxt.PanicOnError(ohlcv)
	}
	ohlcv = this.RequireValue(ohlcv, "watchOHLCV() ohlcv is required")
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(ohlcv).GetLimit(symbolValue, limit)
	}

	ch <- this.FilterBySinceLimit(ohlcv, since, limitResolved, 0, true)
	return nil
}
func (this *Mexc) HandleOHLCV(client any, message any) {
	//
	// spot
	//
	//    {
	//        "d": {
	//            "e": "spot@public.kline.v3.api",
	//            "k": {
	//                "t": 1678642261,
	//                "o": 20626.94,
	//                "c": 20599.69,
	//                "h": 20626.94,
	//                "l": 20597.06,
	//                "v": 27.678686,
	//                "a": 570332.77,
	//                "T": 1678642320,
	//                "i": "Min1"
	//            }
	//        },
	//        "c": "spot@public.kline.v3.api@BTCUSDT@Min1",
	//        "t": 1678642276459,
	//        "s": "BTCUSDT"
	//    }
	//
	// swap
	//
	//   {
	//       "channel": "push.kline",
	//       "data": {
	//         "a": 325653.3287,
	//         "c": 38839,
	//         "h": 38909.5,
	//         "interval": "Min1",
	//         "l": 38833,
	//         "o": 38901.5,
	//         "q": 83808,
	//         "rc": 38839,
	//         "rh": 38909.5,
	//         "rl": 38833,
	//         "ro": 38909.5,
	//         "symbol": "BTC_USDT",
	//         "t": 1651230660
	//       },
	//       "symbol": "BTC_USDT",
	//       "ts": 1651230713067
	//   }
	// protobuf
	//  {
	//    "channel":"spot@public.kline.v3.api.pb@BTCUSDT@Min1",
	//    "symbol":"BTCUSDT",
	//    "symbolId":"2fb942154ef44a4ab2ef98c8afb6a4a7",
	//    "createTime":"1754737941062",
	//    "publicSpotKline":{
	//       "interval":"Min1",
	//       "windowStart":"1754737920",
	//       "openingPrice":"117317.31",
	//       "closingPrice":"117325.26",
	//       "highestPrice":"117341",
	//       "lowestPrice":"117317.3",
	//       "volume":"3.12599854",
	//       "amount":"366804.43",
	//       "windowEnd":"1754737980"
	//    }
	// }
	//
	var parsed any = nil
	var symbol any = nil
	var timeframe *string = nil
	if ccxt.InOp(message, "publicSpotKline") {
		symbol = this.Symbol(this.SafeString(message, "symbol"))
		var data map[string]any = ccxt.MapTyped(this.SafeDict(message, "publicSpotKline", map[string]any{}))
		var timeframeId *string = this.SafeString(data, "interval")
		timeframe = this.FindTimeframe(timeframeId, ccxt.GetValue(this.Options, "timeframes"))
		parsed = this.ParseWsOHLCV(data, this.SafeMarket(symbol))
	} else {
		var d map[string]any = ccxt.SafeDict2Typed(message, "d", "data", map[string]any{})
		var rawOhlcv any = this.SafeDict(d, "k", d)
		var timeframeId *string = this.SafeString2(rawOhlcv, "i", "interval")
		var timeframes any = this.SafeDict(this.Options, "timeframes", map[string]any{})
		timeframe = this.FindTimeframe(timeframeId, timeframes)
		var marketId *string = this.SafeString2(message, "s", "symbol")
		var market map[string]any = this.SafeMarket(marketId)
		symbol = market["symbol"]
		parsed = this.ParseWsOHLCV(rawOhlcv, market)
	}
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add(ccxt.Add(ccxt.Add("candles:", symbol), ":"), timeframe))
	var symbolOhlcvs any = this.SafeDict(this.Ohlcvs, symbol, map[string]any{})
	ccxt.AddElementToObject(this.Ohlcvs, symbol, symbolOhlcvs)
	var stored any = this.SafeValue(symbolOhlcvs, timeframe)
	if ccxt.IsEqual(stored, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored = ccxt.NewArrayCacheByTimestamp(limit)
		if timeframe != nil {
			ccxt.AddElementToObject(symbolOhlcvs, timeframe, stored)
		}
	}
	stored.(ccxt.Appender).Append(parsed)
	client.(ccxt.ClientInterface).Resolve(stored, messageHash)
}
func (this *Mexc) ParseWsOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	// spot
	//
	//    {
	//        "t": 1678642260,
	//        "o": 20626.94,
	//        "c": 20599.69,
	//        "h": 20626.94,
	//        "l": 20597.06,
	//        "v": 27.678686,
	//        "a": 570332.77,
	//        "T": 1678642320,
	//        "i": "Min1"
	//    }
	//
	// swap
	//    {
	//       "symbol": "BTC_USDT",
	//       "interval": "Min1",
	//       "t": 1680055080,
	//       "o": 27301.9,
	//       "c": 27301.8,
	//       "h": 27301.9,
	//       "l": 27301.8,
	//       "a": 8.19054,
	//       "q": 3,
	//       "ro": 27301.8,
	//       "rc": 27301.8,
	//       "rh": 27301.8,
	//       "rl": 27301.8
	//     }
	// protobuf
	//
	//       "interval":"Min1",
	//       "windowStart":"1754737920",
	//       "openingPrice":"117317.31",
	//       "closingPrice":"117325.26",
	//       "highestPrice":"117341",
	//       "lowestPrice":"117317.3",
	//       "volume":"3.12599854",
	//       "amount":"366804.43",
	//       "windowEnd":"1754737980"
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var volume *float64 = this.SafeNumber2(ohlcv, "v", "volume")
	// MEXC swap websocket klines publish contracts volume in `q`,
	// while spot/protobuf uses `v`/`volume`.
	if (market != nil) && (!ccxt.IsEqual(this.SafeBool(market, "spot"), true)) && (volume == nil) {
		volume = this.SafeNumber2(ohlcv, "q", "v")
	}
	return []any{this.SafeTimestamp2(ohlcv, "t", "windowStart"), this.SafeNumber2(ohlcv, "o", "openingPrice"), this.SafeNumber2(ohlcv, "h", "highestPrice"), this.SafeNumber2(ohlcv, "l", "lowestPrice"), this.SafeNumber2(ohlcv, "c", "closingPrice"), volume}
}

/**
 * @method
 * @name mexc#watchOrderBook
 * @see https://www.mexc.com/api-docs/spot-v3/websocket-market-streams/diffdepth-stream // spot
 * @see https://www.mexc.com/api-docs/futures/websocket-api/order-book-depth // swap
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.frequency] the frequency of the order book updates, default is '10ms', can be '100ms' or '10ms
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Mexc) WatchOrderBookAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Mexc) watchOrderBookBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var symbolValue *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "orderbook:" + *symbolValue
	var orderbook any = nil
	if ccxt.GetValue(market, "spot") == true {
		var frequencyparamsFrequencyVariable []any = this.HandleOptionStringAndParams(params, "watchOrderBook", "frequency", "100ms")
		var frequency *string = ccxt.SafeStringPtr(ccxt.GetValue(frequencyparamsFrequencyVariable, 0))
		var paramsFrequency map[string]any = ccxt.MapTyped(ccxt.GetValue(frequencyparamsFrequencyVariable, 1))
		var channel *string = ccxt.SafeStringPtr(ccxt.Add("spot@public.aggre.depth.v3.api.pb@"+*frequency+"@", market["id"]))

		orderbook = (<-this.WatchSpotPublicAsync(channel, messageHash, paramsFrequency))
		ccxt.PanicOnError(orderbook)
	} else {
		var channel string = "sub.depth"
		var requestParams map[string]any = map[string]any{
			"symbol": market["id"],
		}

		orderbook = (<-this.WatchSwapPublicAsync(channel, messageHash, requestParams, params))
		ccxt.PanicOnError(orderbook)
	}
	orderbook = this.RequireValue(orderbook, "watchOrderBook() orderbook is required")

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}
func (this *Mexc) HandleOrderBookSubscription(client any, message map[string]any) {
	// spot
	//     { id: 0, code: 0, msg: "spot@public.increase.depth.v3.api@BTCUSDT" }
	//
	var msg *string = this.SafeString(message, "msg", "")
	var parts []string = strings.Split(*msg, "@")
	var marketId *string = this.SafeString(parts, 2)
	var symbol *string = this.SafeSymbol(marketId)
	ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook(map[string]any{}))
}
func (this *Mexc) GetCacheIndex(orderbook any, cache any) any {
	// return the first index of the cache that can be applied to the orderbook or -1 if not possible
	var nonce *int64 = this.SafeInteger(orderbook, "nonce")
	var firstDelta map[string]any = ccxt.SafeMapTyped(cache, 0)
	var firstDeltaNonce *int64 = this.SafeIntegerN(firstDelta, []any{"r", "version", "fromVersion"})
	if (nonce == nil) || (firstDeltaNonce == nil) {
		return ccxt.OpNeg(1)
	}
	if ccxt.IsLessThan(nonce, ccxt.Subtract(firstDeltaNonce, 1)) {
		return ccxt.OpNeg(1)
	}
	for i := 0; i < ccxt.GetArrayLength(cache); i++ {
		var delta map[string]any = ccxt.SafeMapTyped(cache, i)
		var deltaNonce *int64 = this.SafeIntegerN(delta, []any{"r", "version", "fromVersion"})
		if deltaNonce == nil {
			continue
		}
		if nonce == nil || (deltaNonce != nil && *deltaNonce >= *nonce) {
			return i
		}
	}
	return ccxt.GetArrayLength(cache)
}
func (this *Mexc) HandleOrderBook(client any, message any) {
	//
	// spot
	//    {
	//        "c": "spot@public.increase.depth.v3.api@BTCUSDT",
	//        "d": {
	//            "asks": [{
	//                "p": "20290.89",
	//                "v": "0.000000"
	//            }],
	//            "e": "spot@public.increase.depth.v3.api",
	//            "r": "3407459756"
	//        },
	//        "s": "BTCUSDT",
	//        "t": 1661932660144
	//    }
	//
	//
	//
	// swap
	//  {
	//      "channel":"push.depth",
	//      "data":{
	//         "asks":[
	//            [
	//               39146.5,
	//               11264,
	//               1
	//            ]
	//         ],
	//         "bids":[
	//            [
	//               39144,
	//               35460,
	//               1
	//            ]
	//         ],
	//         "end":4895965272,
	//         "begin":4895965271
	//      },
	//      "symbol":"BTC_USDT",
	//      "ts":1651239652372
	//  }
	// protofbuf
	// {
	//      "channel":"spot@public.aggre.depth.v3.api.pb@100ms@BTCUSDT",
	//      "symbol":"BTCUSDT",
	//      "sendTime":"1754741322152",
	//      "publicAggreDepths":{
	//          "asks":[
	//              {
	//                  "price":"117145.49",
	//                  "quantity":"0"
	//              }
	//          ],
	//          "bids":[
	//              {
	//                  "price":"117053.41",
	//                  "quantity":"1.86837271"
	//              }
	//          ],
	//          "eventType":"spot@public.aggre.depth.v3.api.pb@100ms",
	//          "fromVersion":"43296363236",
	//          "toVersion":"43296363255"
	//      }
	// }
	//
	var data any = this.SafeDictN(message, []any{"d", "data", "publicAggreDepths"})
	var marketId *string = this.SafeString2(message, "s", "symbol")
	var symbol *string = this.SafeSymbol(marketId)
	var messageHash string = "orderbook:" + *symbol
	var subscription map[string]any = ccxt.SafeMapTyped(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
	var limit *int64 = this.SafeInteger(subscription, "limit")
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.OrderBook())
	}
	var storedOrderBook any = ccxt.GetValue(this.Orderbooks, symbol)
	var nonce *int64 = this.SafeInteger(storedOrderBook, "nonce")
	var shouldReturn bool = false
	if nonce == nil {
		var cacheLength int = ccxt.GetArrayLength(storedOrderBook.(ccxt.OrderBookInterface).GetCache())
		var snapshotDelay any = this.HandleOption("watchOrderBook", "snapshotDelay", 25)
		if ccxt.IsEqual(cacheLength, snapshotDelay) {
			this.Spawn(this.LoadOrderBookAsync, client, messageHash, symbol, limit, map[string]any{})
		}
		ccxt.AppendToArray(storedOrderBook.(ccxt.OrderBookInterface).GetCache(), data)
		return
	}

	{
		func(this *Mexc) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Mexc) any {
						// catch block:
						ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
						client.(ccxt.ClientInterface).Reject(e, messageHash)
						// return
						shouldReturn = true
						return nil
					}(this)
				}
			}()
			// try block:
			this.HandleDelta(storedOrderBook, data)
			var timestamp *int64 = this.SafeIntegerN(message, []any{"t", "ts", "sendTime"})
			ccxt.AddElementToObject(storedOrderBook, "timestamp", timestamp)
			ccxt.AddElementToObject(storedOrderBook, "datetime", this.Iso8601(timestamp))
			return nil
		}(this)

	}
	if shouldReturn {
		return // go requirement
	}
	client.(ccxt.ClientInterface).Resolve(storedOrderBook, messageHash)
}
func (this *Mexc) HandleBooksideDelta(bookside any, bidasks any) {
	//
	//    [{
	//        "p": "20290.89",
	//        "v": "0.000000"
	//    }]
	//
	for i := 0; i < ccxt.GetArrayLength(bidasks); i++ {
		var bidask any = ccxt.GetValue(bidasks, i)
		if ccxt.IsArray(bidask) {
			bookside.(ccxt.IOrderBookSide).StoreArray(bidask)
		} else {
			var price *float64 = this.SafeFloat2(bidask, "p", "price")
			var amount *float64 = this.SafeFloat2(bidask, "v", "quantity")
			bookside.(ccxt.IOrderBookSide).Store(price, amount)
		}
	}
}
func (this *Mexc) HandleDelta(orderbook any, delta any) {
	var existingNonce *int64 = this.SafeInteger(orderbook, "nonce")
	var deltaNonce *int64 = this.SafeIntegerN(delta, []any{"r", "version", "fromVersion"})
	if (deltaNonce != nil) && (existingNonce != nil) && (*deltaNonce < *existingNonce) {
		// even when doing < comparison, this happens: https://app.travis-ci.com/github/ccxt/ccxt/builds/269234741#L1809
		// so, we just skip old updates
		return
	}
	ccxt.AddElementToObject(orderbook, "nonce", deltaNonce)
	var asks []any = ccxt.SafeListTypedDefault(delta, "asks", []any{})
	var bids []any = ccxt.SafeListTypedDefault(delta, "bids", []any{})
	var asksOrderSide any = ccxt.GetValue(orderbook, "asks")
	var bidsOrderSide any = ccxt.GetValue(orderbook, "bids")
	this.HandleBooksideDelta(asksOrderSide, asks)
	this.HandleBooksideDelta(bidsOrderSide, bids)
}

/**
 * @method
 * @name mexc#watchTrades
 * @see https://www.mexc.com/api-docs/spot-v3/websocket-market-streams/trade-streams // spot
 * @see https://www.mexc.com/api-docs/futures/websocket-api/deal // swap
 * @description get the list of most recent trades for a particular symbol
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Mexc) WatchTradesAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Mexc) watchTradesBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var symbolValue *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "trades:" + *symbolValue
	var trades any = nil
	if ccxt.GetValue(market, "spot") == true {
		var channel *string = ccxt.SafeStringPtr(ccxt.Add("spot@public.aggre.deals.v3.api.pb@100ms@", market["id"]))

		trades = (<-this.WatchSpotPublicAsync(channel, messageHash, params))
		ccxt.PanicOnError(trades)
	} else {
		var channel string = "sub.deal"
		var requestParams map[string]any = map[string]any{
			"symbol": market["id"],
		}

		trades = (<-this.WatchSwapPublicAsync(channel, messageHash, requestParams, params))
		ccxt.PanicOnError(trades)
	}
	trades = this.RequireValue(trades, "watchTrades() trades is required")
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(trades).GetLimit(symbolValue, limit)
	}

	ch <- this.FilterBySinceLimit(trades, since, limitResolved, "timestamp", true)
	return nil
}
func (this *Mexc) HandleTrades(client any, message any) {
	// protobuf
	// {
	// "channel": "spot@public.aggre.deals.v3.api.pb@100ms@BTCUSDT",
	// "publicdeals": {
	//     "dealsList": [
	//     {
	//         "price": "93220.00", // ccxt.Trade price
	//         "quantity": "0.04438243", // ccxt.Trade quantity
	//         "tradetype": 2, // ccxt.Trade type (1: Buy, 2: Sell)
	//         "time": 1736409765051 // ccxt.Trade time
	//     }
	//     ],
	//     "eventtype": "spot@public.aggre.deals.v3.api.pb@100ms" // Event type
	// },
	// "symbol": "BTCUSDT", // Trading pair
	// "sendtime": 1736409765052 // Event time
	// }
	//
	//    {
	//        "c": "spot@public.deals.v3.api@BTCUSDT",
	//        "d": {
	//            "deals": [{
	//                "p": "20382.70",
	//                "v": "0.043800",
	//                "S": 1,
	//                "t": 1678593222456,
	//            }, ],
	//            "e": "spot@public.deals.v3.api",
	//        },
	//        "s": "BTCUSDT",
	//        "t": 1678593222460,
	//    }
	//
	// swap
	//     {
	//         "symbol": "BTC_USDT",
	//         "data": [
	//            {
	//                "p": 114350.4,
	//                "v": 4,
	//                "T": 2,
	//                "O": 3,
	//                "M": 2,
	//                "t": 1760368563597
	//            }
	//         ],
	//         "channel": "push.deal",
	//         "ts": 1680055941870
	//     }
	//
	var marketId *string = this.SafeString2(message, "s", "symbol")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = "trades:" + *symbol
	var stored any = this.SafeValue(this.Trades, symbol)
	if ccxt.IsEqual(stored, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		stored = ccxt.NewArrayCache(limit)
		ccxt.AddElementToObject(this.Trades, symbol, stored)
	}
	var d any = this.SafeDictN(message, []any{"d", "publicAggreDeals"})
	var trades any = this.SafeList2(d, "deals", "dealsList", []any{d})
	if ccxt.IsEqual(d, nil) {
		trades = this.SafeList(message, "data", []any{})
	}
	for j := 0; j < ccxt.GetArrayLength(trades); j++ {
		var parsedTrade any = nil
		if market["spot"] == true {
			parsedTrade = this.ParseWsTrade(ccxt.GetValue(trades, j), market)
		} else {
			parsedTrade = this.ParseTrade(ccxt.GetValue(trades, j), market)
		}
		stored.(ccxt.Appender).Append(parsedTrade)
	}
	client.(ccxt.ClientInterface).Resolve(stored, messageHash)
}

/**
 * @method
 * @name mexc#watchMyTrades
 * @see https://www.mexc.com/api-docs/spot-v3/websocket-user-data-streams/spot-account-deals // spot
 * @see https://www.mexc.com/api-docs/futures/websocket-api/fill-details // swap
 * @description watches information on multiple trades made by the user
 * @param {string} symbol unified market symbol of the market trades were made in
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trade structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Mexc) WatchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Mexc) watchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var messageHash any = "myTrades"
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	var symbolResolved any = func() any {
		if !ccxt.IsEqual(market, nil) {
			return ccxt.GetValue(market, "symbol")
		}
		return nil
	}()
	if symbol != nil {
		messageHash = ccxt.Add(ccxt.Add(messageHash, ":"), symbolResolved)
	}
	typeVar, paramsMarketType := this.HandleMarketTypeAndParams("watchMyTrades", market, params)
	var trades any = nil
	if typeVar != nil && *typeVar == "spot" {
		var channel string = "spot@private.deals.v3.api.pb"

		trades = (<-this.WatchSpotPrivateAsync(channel, messageHash, paramsMarketType))
		ccxt.PanicOnError(trades)
	} else {

		trades = (<-this.WatchSwapPrivateAsync(messageHash, paramsMarketType))
		ccxt.PanicOnError(trades)
	}
	trades = this.RequireValue(trades, "watchMyTrades() trades is required")
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(trades).GetLimit(symbolResolved, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(trades, symbolResolved, since, limitResolved, true)
	return nil
}
func (this *Mexc) HandleMyTrade(client any, message any, optionalArgs ...any) {
	//
	//    {
	//        "c": "spot@private.deals.v3.api",
	//        "d": {
	//            "p": "22339.99",
	//            "v": "0.000235",
	//            "S": 1,
	//            "T": 1678670940695,
	//            "t": "9f6a47fb926442e496c5c4c104076ae3",
	//            "c": '',
	//            "i": "e2b9835d1b6745f8a10ab74a81a16d50",
	//            "m": 0,
	//            "st": 0
	//        },
	//        "s": "BTCUSDT",
	//        "t": 1678670940700
	//    }
	//    {
	//      channel: "spot@private.deals.v3.api.pb",
	//      symbol: "MXUSDT",
	//      sendTime: 1736417034332,
	//      privateDeals {
	//        price: "3.6962",
	//        quantity: "1",
	//        amount: "3.6962",
	//        tradeType: 2,
	//        tradeId: "505979017439002624X1",
	//        orderId: "C02__505979017439002624115",
	//        feeAmount: "0.0003998377369698171",
	//        feeCurrency: "MX",
	//        time: 1736417034280
	//      }
	// }
	//
	var subscription map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = subscription
	var messageHash string = "myTrades"
	var data any = this.SafeDictN(message, []any{"d", "data", "privateDeals"})
	var futuresMarketId *string = this.SafeString(data, "symbol")
	var marketId *string = this.SafeString2(message, "s", "symbol", futuresMarketId)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var trade any = nil
	if market["spot"] == true {
		trade = this.ParseWsTrade(data, market)
	} else if !ccxt.IsEqual(data, nil) {
		trade = this.ParseTrade(data, market)
	} else {
		return
	}
	var trades any = this.MyTrades
	if ccxt.IsEqual(trades, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		trades = ccxt.NewArrayCacheBySymbolById(limit)
		this.MyTrades = trades
	}
	trades.(ccxt.Appender).Append(trade)
	client.(ccxt.ClientInterface).Resolve(trades, messageHash)
	var symbolSpecificMessageHash string = messageHash + ":" + *symbol
	client.(ccxt.ClientInterface).Resolve(trades, symbolSpecificMessageHash)
}
func (this *Mexc) ParseWsTrade(trade any, optionalArgs ...any) any {
	//
	// public trade (protobuf)
	//    {
	//        "p": "20382.70",
	//        "v": "0.043800",
	//        "S": 1,
	//        "t": 1678593222456,
	//    }
	// private trade
	//    {
	//        "S": 1,
	//        "T": 1661938980268,
	//        "c": "",
	//        "i": "c079b0fcb80a46e8b128b281ce4e4f38",
	//        "m": 1,
	//        "p": "1.008",
	//        "st": 0,
	//        "t": "4079b1522a0b40e7919f609e1ea38d44",
	//        "v": "5"
	//    }
	//
	//   d: {
	//       p: '1.0005',
	//       v: '5.71',
	//       a: '5.712855',
	//       S: 1,
	//       T: 1714325698237,
	//       t: 'edafcd9fdc2f426e82443d114691f724',
	//       c: '',
	//       i: 'C02__413321238354677760043',
	//       m: 0,
	//       st: 0,
	//       n: '0.005712855',
	//       N: 'USDT'
	//   }
	// protobuf
	//
	//     {
	//        price: "3.6962",
	//        quantity: "1",
	//        amount: "3.6962",
	//        tradeType: 2,
	//        tradeId: "505979017439002624X1",
	//        orderId: "C02__505979017439002624115",
	//        feeAmount: "0.0003998377369698171",
	//        feeCurrency: "MX",
	//        time: 1736417034280
	//      }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger2(trade, "T", "time")
	var tradeId *string = this.SafeString2(trade, "t", "tradeId")
	if timestamp == nil {
		timestamp = this.SafeInteger(trade, "t")
		tradeId = nil
	}
	var priceString *string = this.SafeString2(trade, "p", "price")
	var amountString *string = this.SafeString2(trade, "v", "quantity")
	var rawSide *string = this.SafeString2(trade, "S", "tradeType")
	var side string = "sell"
	if rawSide != nil && *rawSide == "1" {
		side = "buy"
	}
	var isMaker *int64 = this.SafeInteger(trade, "m")
	var feeAmount *string = this.SafeString2(trade, "n", "feeAmount")
	var feeCurrencyId *string = this.SafeString2(trade, "N", "feeCurrency")
	return this.SafeTrade(map[string]any{
		"info":      trade,
		"id":        tradeId,
		"order":     this.SafeString2(trade, "i", "orderId"),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"symbol":    this.SafeSymbol(nil, market),
		"type":      nil,
		"side":      side,
		"takerOrMaker": func() string {
			if (isMaker != nil) && (isMaker == nil || *isMaker != 0) {
				return "maker"
			}
			return "taker"
		}(),
		"price":  priceString,
		"amount": amountString,
		"cost":   this.SafeString(trade, "amount"),
		"fee": map[string]any{
			"cost":     feeAmount,
			"currency": this.SafeCurrencyCode(feeCurrencyId),
		},
	}, market)
}

