func (this *Mexc) HandleUnsubscriptions(client any, messageHashes any) {
	for i := 0; i < ccxt.GetArrayLength(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(ccxt.GetValue(messageHashes, i))
		var subMessageHash string = strings.Replace(*messageHash, "unsubscribe:", "", 1)
		this.CleanUnsubscription(ccxt.AsClient(client), subMessageHash, messageHash)
		if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "ticker")
		}() >= 0 {
			var symbol any = strings.Replace(*messageHash, "unsubscribe:ticker:", "", 1)
			if ccxt.GetIndexOf(symbol, "unsubscribe") >= 0 {
				// unWatchTickers
				var symbols []string = ccxt.ObjectKeys(this.Tickers)
				for j := 0; j < len(symbols); j++ {
					ccxt.Remove(this.Tickers, ccxt.GetValue(symbols, j))
				}
			} else if ccxt.InOp(this.Tickers, symbol) {
				ccxt.Remove(this.Tickers, symbol)
			}
		} else if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "bidask")
		}() >= 0 {
			var symbol any = strings.Replace(*messageHash, "unsubscribe:bidask:", "", 1)
			if ccxt.InOp(this.Bidsasks, symbol) {
				ccxt.Remove(this.Bidsasks, symbol)
			}
		} else if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "candles")
		}() >= 0 {
			var splitHashes []string = strings.Split(*messageHash, ":")
			var symbol any = ccxt.DerefScalar(this.SafeString(splitHashes, 2))
			var splitHashesLength int = len(splitHashes) // hoisted - inline .length within conditionals becomes strlen for php, fatal on arrays
			if splitHashesLength > 4 {
				symbol = ccxt.Add(symbol, ccxt.Add(":", this.SafeString(splitHashes, 3)))
			}
			if (!ccxt.IsEqual(symbol, nil)) && (ccxt.InOp(this.Ohlcvs, symbol)) {
				ccxt.Remove(this.Ohlcvs, symbol)
			}
		} else if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "orderbook")
		}() >= 0 {
			var symbol any = strings.Replace(*messageHash, "unsubscribe:orderbook:", "", 1)
			if ccxt.InOp(this.Orderbooks, symbol) {
				ccxt.Remove(this.Orderbooks, symbol)
			}
		} else if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "trades")
		}() >= 0 {
			var symbol any = strings.Replace(*messageHash, "unsubscribe:trades:", "", 1)
			if ccxt.InOp(this.Trades, symbol) {
				ccxt.Remove(this.Trades, symbol)
			}
		} else if func() int {
			if messageHash == nil {
				return -1
			}
			return strings.Index(*messageHash, "fundingRate")
		}() >= 0 {
			var symbol any = strings.Replace(*messageHash, "unsubscribe:fundingRate:", "", 1)
			if ccxt.InOp(this.FundingRates, symbol) {
				ccxt.Remove(this.FundingRates, symbol)
			}
		}
	}
}
func (this *Mexc) AuthenticateAsync(subscriptionHash any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, subscriptionHash, optionalArgs...)
	return ch
}
func (this *Mexc) authenticateBody(ch chan any, subscriptionHash any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// we only need one listenKey since ccxt shares connections
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var listenKey *string = this.SafeString(this.Options, "listenKey")
	if listenKey != nil {

		ch <- listenKey
		return nil
	}
	// guard against concurrent listenKey requests with a future on the base
	// spot ws client - the first caller fetches the listenKey, concurrent
	// callers wait on the future and resume when the listenKey is ready,
	// otherwise the user-data subscriptions would be split across two connections
	var client ccxt.ClientInterface = this.Client(ccxt.GetValue(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "spot"))
	var messageHash string = "authenticate:listenKey"
	var isFetching *bool = this.SafeBool(this.Options, "listenKeyFetching", false)
	if isFetching != nil && *isFetching == true {

		ccxt.PanicOnError((<-client.(ccxt.ClientInterface).Future(messageHash)))

		ch <- this.SafeString(this.Options, "listenKey")
		return nil
	}
	this.Options.Store("listenKeyFetching", true)
	client.(ccxt.ClientInterface).Future(messageHash) // created ahead of the request below, so concurrent callers can find it
	var response map[string]any = nil

	{
		func(this *Mexc) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Mexc) any {
						// catch block:
						this.Options.Store("listenKeyFetching", false)
						client.(ccxt.ClientInterface).Reject(e, messageHash)
						panic(e)

					}(this)
				}
			}()
			// try block:

			response = ccxt.MapTyped(ccxt.PanicOnError((<-this.SpotPrivatePostUserDataStream(params)).Raw))
			return nil
		}(this)

	}
	this.Options.Store("listenKeyFetching", false)
	//
	//    {
	//        "listenKey": "pqia91ma19a5s61cv6a81va65sdf19v8a65a1a5s61cv6a81va65sdf19v8a65a1"
	//    }
	//
	listenKey = this.SafeString(response, "listenKey")
	this.Options.Store("listenKey", listenKey)
	client.(ccxt.ClientInterface).Resolve(listenKey, messageHash)
	var listenKeyRefreshRate *int64 = this.SafeInteger(this.Options, "listenKeyRefreshRate", 1200000)
	this.Delay(listenKeyRefreshRate, this.KeepAliveListenKeyAsync, listenKey, params)

	ch <- listenKey
	return nil
}
func (this *Mexc) KeepAliveListenKeyAsync(listenKey any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.keepAliveListenKeyBody(ch, listenKey, optionalArgs...)
	return ch
}
func (this *Mexc) keepAliveListenKeyBody(ch chan any, listenKey any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if ccxt.IsEqual(listenKey, nil) {

		return nil
	}
	var request map[string]any = map[string]any{
		"listenKey": listenKey,
	}

	{
		func(this *Mexc) (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func(this *Mexc) any {
						// catch block:
						var wsUrl *string = this.SafeString(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"), "spot")
						if wsUrl == nil {
							panic(ccxt.ExchangeError(this.Id + " keepAliveListenKey() has no spot websocket url"))
						}
						var url any = ccxt.Add(*wsUrl+"?listenKey=", listenKey)
						var client ccxt.ClientInterface = this.Client(url)
						this.Options.Store("listenKey", nil)
						client.(ccxt.ClientInterface).Reject(error)
						ccxt.Remove(this.Clients, url)
						return nil
					}(this)
				}
			}()
			// try block:

			ccxt.PanicOnError((<-this.SpotPrivatePutUserDataStream(this.Extend(request, params))).Raw)
			var listenKeyRefreshRate *int64 = this.SafeInteger(this.Options, "listenKeyRefreshRate", 1200000)
			this.Delay(listenKeyRefreshRate, this.KeepAliveListenKeyAsync, listenKey, params)
			return nil
		}(this)

	}
	return nil
}
func (this *Mexc) HandlePong(client any, message any) any {
	client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
	return message
}
func (this *Mexc) HandleSubscriptionStatus(client any, message any) {
	//
	//    {
	//        "id": 0,
	//        "code": 0,
	//        "msg": "spot@public.increase.depth.v3.api@BTCUSDT"
	//    }
	// ccxt.Set the default to an empty string if the message is empty during the test.
	var msg *string = this.SafeString(message, "msg", "")
	if msg != nil && *msg == "PONG" {
		this.HandlePong(client, message)
	} else if func() int {
		if msg == nil {
			return -1
		}
		return strings.Index(*msg, "@")
	}() > -1 {
		var parts []string = strings.Split(*msg, "@")
		var channel *string = this.SafeString(parts, 1)
		var methods map[string]any = map[string]any{
			"public.increase.depth.v3.api": this.HandleOrderBookSubscription,
			"public.aggre.depth.v3.api.pb": this.HandleOrderBookSubscription,
		}
		var method any = this.SafeValue(methods, channel)
		if !ccxt.IsEqual(method, nil) {
			ccxt.CallDynamically(method, client, message)
		}
	}
}
func (this *Mexc) HandleProtobufMessage(client any, message any) any {
	// protobuf message decoded
	//  {
	//    "channel":"spot@public.kline.v3.api.pb@BTCUSDT@Min1",
	//    "symbol":"BTCUSDT",
	//    "symbolId":"2fb942154ef44a4ab2ef98c8afb6a4a7",
	//    "createTime":"1754737941062",
	//    "publicSpotKline":{
	//       "interval":"Min1",
	//       "windowStart":"1754737920",
	//       "openingPrice":"117317.31",
	//       "closingPrice":"117325.26",
	//       "highestPrice":"117341",
	//       "lowestPrice":"117317.3",
	//       "volume":"3.12599854",
	//       "amount":"366804.43",
	//       "windowEnd":"1754737980"
	//    }
	// }
	var channel *string = this.SafeString(message, "channel", "")
	var channelParts []string = strings.Split(*channel, "@")
	var channelId *string = this.SafeString(channelParts, 1)
	if channelId != nil && *channelId == "public.kline.v3.api.pb" {
		this.HandleOHLCV(client, message)
	} else if channelId != nil && *channelId == "public.aggre.deals.v3.api.pb" {
		this.HandleTrades(client, message)
	} else if channelId != nil && *channelId == "public.aggre.bookTicker.v3.api.pb" {
		this.HandleTicker(client, message)
	} else if channelId != nil && *channelId == "public.aggre.depth.v3.api.pb" {
		this.HandleOrderBook(client, message)
	} else if channelId != nil && *channelId == "private.account.v3.api.pb" {
		this.HandleBalance(client, message)
	} else if channelId != nil && *channelId == "private.deals.v3.api.pb" {
		this.HandleMyTrade(client, message)
	} else if channelId != nil && *channelId == "private.orders.v3.api.pb" {
		this.HandleOrder(client, message)
	}
	return true
}
func (this *Mexc) HandleMessage(client any, message any) {
	if ccxt.IsString(message) {
		if ccxt.IsEqual(message, "Invalid listen key") {
			error := ccxt.AuthenticationError(this.Id + " invalid listen key")
			client.(ccxt.ClientInterface).Reject(error)
			return
		}
	}
	if this.IsBinaryMessage(message) {
		var decodedMessage any = this.DecodeProtoMsg(message)
		this.HandleProtobufMessage(client, decodedMessage)
		return
	}
	if ccxt.InOp(message, "msg") {
		this.HandleSubscriptionStatus(client, message)
		return
	}
	var c *string = this.SafeString(message, "c")
	var channel any = nil
	if c == nil {
		channel = this.SafeString(message, "channel")
	} else {
		var parts []string = strings.Split(*c, "@")
		channel = this.SafeString(parts, 1, "")
	}
	var methods map[string]any = map[string]any{
		"public.deals.v3.api":          this.HandleTrades,
		"push.deal":                    this.HandleTrades,
		"public.kline.v3.api":          this.HandleOHLCV,
		"push.kline":                   this.HandleOHLCV,
		"public.bookTicker.v3.api":     this.HandleTicker,
		"public.miniTicker.v3.api":     this.HandleTicker,
		"public.miniTickers.v3.api":    this.HandleTickers,
		"push.ticker":                  this.HandleTicker,
		"push.tickers":                 this.HandleTickers,
		"public.increase.depth.v3.api": this.HandleOrderBook,
		"push.depth":                   this.HandleOrderBook,
		"private.orders.v3.api":        this.HandleOrder,
		"push.personal.order":          this.HandleOrder,
		"private.account.v3.api":       this.HandleBalance,
		"push.personal.asset":          this.HandleBalance,
		"private.deals.v3.api":         this.HandleMyTrade,
		"push.personal.order.deal":     this.HandleMyTrade,
		"pong":                         this.HandlePong,
		"push.funding.rate":            this.HandleFundingRate,
	}
	if (!ccxt.IsEqual(channel, nil)) && (ccxt.InOp(methods, channel)) {
		var method any = ccxt.GetValue(methods, channel)
		ccxt.CallDynamically(method, client, message)
	}
}
func (this *Mexc) Ping(client any) any {
	return map[string]any{
		"method": "ping",
	}
}

